exercise.referenceSolution:
#include <iostream>
#include <print>

class Volume {
public:
    int get() const {
        return value_;
    }

    void set(int value) {
        if (value < 0) {
            value = 0;
        }
        if (value > 100) {
            value = 100;
        }
        value_ = value;
    }

private:
    int value_ = 50;
};

int main() {
    Volume v;
    char command;
    int n;
    while (std::cin >> command >> n) {
        if (command == '+') {
            v.set(v.get() + n);
        } else if (command == '-') {
            v.set(v.get() - n);
        } else {
            v.set(n);
        }
        std::println("{}", v.get());
    }
    return 0;
}

