#include <cstdlib>
#include <iostream>
#include <print>

class Elevator {
public:
    int floor() const {
        return floor_;
    }

    int travelled() const {
        return travelled_;
    }

    bool move_to(int target) {
        if (target < 1 || target > 20) {
            return false;
        }
        travelled_ += std::abs(target - floor_);
        floor_ = target;
        return true;
    }

private:
    int floor_ = 1;
    int travelled_ = 0;
};

int main() {
    Elevator lift;
    int target;
    while (std::cin >> target) {
        if (lift.move_to(target)) {
            std::println("этаж {}", lift.floor());
        } else {
            std::println("нет этажа {}", target);
        }
    }
    std::println("пройдено {} этажей", lift.travelled());
    return 0;
}

