#include <algorithm>
#include <iostream>
#include <print>
#include <string>

class Window {
public:
    void move(int dx, int dy) {
        x_ = std::clamp(x_ + dx, 0, screen_w - w_);
        y_ = std::clamp(y_ + dy, 0, screen_h - h_);
    }

    void resize(int w, int h) {
        w_ = std::clamp(w, min_size, screen_w - x_);
        h_ = std::clamp(h, min_size, screen_h - y_);
    }

    void print() const {
        std::println("{} {} {} {}", x_, y_, w_, h_);
    }

private:
    static constexpr int screen_w = 1920;
    static constexpr int screen_h = 1080;
    static constexpr int min_size = 100;
    int x_ = 0;
    int y_ = 0;
    int w_ = 800;
    int h_ = 600;
};

int main() {
    Window window;
    std::string command;
    int a, b;
    while (std::cin >> command >> a >> b) {
        if (command == "move") {
            window.move(a, b);
        } else {
            window.resize(a, b);
        }
        window.print();
    }
    return 0;
}

