class Level {
public:
    int get() const { return level_; }
    void up() { if (level_ < 3) level_++; }
    void down() { if (level_ > 1) level_--; }

private:
    int level_ = 1;
};

int main() {
    Level l;
    l.up(); l.up(); l.up(); l.up();
    l.down();
    std::println("{}", l.get());
    return 0;
}

#include <print>

class Stock {
public:
    int count() const { return count_; }
    bool take(int n) {
        if (n > count_) return false;
        count_ -= n;
        return true;
    }

private:
    int count_ = 10;
};

int main() {
    Stock s;
    bool a = s.take(4), b = s.take(7), c = s.take(6);
    std::println("{} {} {} {}", a, b, c, s.count());
    return 0;
}
